+#[derive(Debug, PartialEq, Eq)]
+pub struct Response {
+    pub status: u16,
+    pub count: u64,
+}
+
+/// The API's state transition. Only a GET to /ping changes the counter.
+pub fn handle(path: &str, method: Method, pong_count: u64) -> (Response, u64) {
+    if path != "/ping" {
+        return (Response { status: 404, count: pong_count }, pong_count);
+    }
+
+    if method != Method::Get {
+        return (Response { status: 405, count: pong_count }, pong_count);
+    }
+
+    let next_count = pong_count.checked_add(1).expect("pong counter overflow");
+    (Response { status: 200, count: next_count }, next_count)
+}
